import json
from typing import Dict, Any, Optional

class LogEvent:
    def __init__(self, message: str, severity: str, timestamp: int, metadata: Optional[Dict[str, Any]] = None):
        self.message = message
        self.severity = severity
        self.timestamp = timestamp
        self.metadata = metadata if metadata is not None else {}

    def to_json_string(self) -> str:
        event_data = {
            "message": self.message,
            "severity": self.severity,
            "timestamp": self.timestamp,
            "metadata": self.metadata
        }
        return json.dumps(event_data)

import boto3
import os

class CloudWatchLogsClient:
    def __init__(self, region_name: str = 'us-east-1'):
        self.client = boto3.client('logs', region_name=region_name)

    def put_log_event(self, log_group_name: str, log_stream_name: str, message: str, timestamp: int):
        response = self.client.put_log_events(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
            logEvents=[
                {
                    'timestamp': timestamp,
                    'message': message
                },
            ]
        )
        return response

    def filter_log_events(self, log_group_name: str, start_time: int, end_time: int, filter_pattern: str):
        response = self.client.filter_log_events(
            logGroupName=log_group_name,
            startTime=start_time,
            endTime=end_time,\
            filterPattern=filter_pattern
        )
        return response

    def start_query(self, log_group_names: list[str], start_time: int, end_time: int, query_string: str):
        response = self.client.start_query(
            logGroupNames=log_group_names,
            startTime=start_time,
            endTime=end_time,
            queryString=query_string,
        )
        return response

    def get_query_results(self, query_id: str):
        response = self.client.get_query_results(
            queryId=query_id
        )
        return response
